#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_N 40
#define MAX_GRAM 10
#define INF 1000000000

int main() {
    int n, Ma, Mb;
    scanf("%d %d %d", &n, &Ma, &Mb);

    int a[MAX_N], b[MAX_N], c[MAX_N];
    int totalA = 0, totalB = 0;
    for (int i = 0; i < n; i++) {
        scanf("%d %d %d", &a[i], &b[i], &c[i]);
        totalA += a[i];
        totalB += b[i];
    }

    // dp[i][j] = minimum cost to achieve exactly i grams of A and j grams of B
    // using first k packages (we'll use 2D DP with iteration)
    int dp[MAX_N * MAX_GRAM + 1][MAX_N * MAX_GRAM + 1];
    for (int i = 0; i <= totalA; i++) {
        for (int j = 0; j <= totalB; j++) {
            dp[i][j] = INF;
        }
    }
    dp[0][0] = 0;

    for (int k = 0; k < n; k++) {
        // iterate backwards to avoid using same package multiple times
        for (int i = totalA; i >= 0; i--) {
            for (int j = totalB; j >= 0; j--) {
                if (dp[i][j] != INF) {
                    int ni = i + a[k];
                    int nj = j + b[k];
                    if (ni <= totalA && nj <= totalB) {
                        if (dp[i][j] + c[k] < dp[ni][nj]) {
                            dp[ni][nj] = dp[i][j] + c[k];
                        }
                    }
                }
            }
        }
    }

    int minCost = INF;
    // We need A:B = Ma:Mb, so A*Mb == B*Ma
    for (int i = 1; i <= totalA; i++) {
        for (int j = 1; j <= totalB; j++) {
            if (dp[i][j] != INF && i * Mb == j * Ma) {
                if (dp[i][j] < minCost) {
                    minCost = dp[i][j];
                }
            }
        }
    }

    if (minCost == INF) {
        printf("-1\n");
    } else {
        printf("%d\n", minCost);
    }

    return 0;
}

