typedef long long ll;

int N, Ma, Mb;
ll a[40], b[40], c[40], d[40];

typedef struct { ll key; ll cost; } Entry;

int cmp(const void *x, const void *y) {
    Entry *ex = (Entry*)x, *ey = (Entry*)y;
    if (ex->key < ey->key) return -1;
    if (ex->key > ey->key) return 1;
    return 0;
}

Entry table[1<<20];
int tsize;

int main() {
    scanf("%d %d %d", &N, &Ma, &Mb);
    for (int i = 0; i < N; i++) {
        scanf("%lld %lld %lld", &a[i], &b[i], &c[i]);
        d[i] = a[i] * Mb - b[i] * Ma;
    }

    int half1 = N / 2, half2 = N - half1;
    tsize = 0;
    for (int mask = 1; mask < (1 << half1); mask++) {
        ll sd = 0, sc = 0;
        for (int i = 0; i < half1; i++) if (mask >> i & 1) { sd += d[i]; sc += c[i]; }
        table[tsize].key = sd; table[tsize].cost = sc; tsize++;
    }
    qsort(table, tsize, sizeof(Entry), cmp);
    // Keep only minimum cost per key
    // Actually we need minimum cost for each key
    // After sort, merge duplicates

    ll ans = LLONG_MAX;
    for (int mask = 0; mask < (1 << half2); mask++) {
        ll sd = 0, sc = 0;
        for (int i = 0; i < half2; i++) if (mask >> i & 1) { sd += d[half1+i]; sc += c[half1+i]; }
        ll target = -sd;
        // binary search in table
        int lo = 0, hi = tsize - 1;
        while (lo <= hi) {
            int mid = (lo+hi)/2;
            if (table[mid].key == target) {
                if (sc + table[mid].cost < ans) ans = sc + table[mid].cost;
                for (int j = mid-1; j >= 0 && table[j].key == target; j--) if (sc+table[j].cost < ans) ans = sc+table[j].cost;
                for (int j = mid+1; j < tsize && table[j].key == target; j++) if (sc+table[j].cost < ans) ans = sc+table[j].cost;
                break;
            } else if (table[mid].key < target) lo = mid+1; else hi = mid-1;
        }
        if (mask == 0 && sd == 0 && sc == 0) {} // skip empty set handled
    }
    if (ans == LLONG_MAX) printf("-1\n"); else printf("%lld\n", ans);
}

#include <stdio.h>
