#define INF 1000000000

static inline int min(int a, int b) { return a < b ? a : b; }

int main(void) {
    int N, Ma, Mb;
    if (scanf("%d %d %d", &N, &Ma, &Mb) != 3) return 0;

    int a[41], b[41], c[41];
    int sumA = 0, sumB = 0;

    for (int i = 0; i < N; i++) {
        scanf("%d %d %d", &a[i], &b[i], &c[i]);
        sumA += a[i];
        sumB += b[i];
    }

    static int dp[401][401];
    static int ndp[401][401];

    for (int i = 0; i <= sumA; i++) {
        for (int j = 0; j <= sumB; j++) {
            dp[i][j] = INF;
        }
    }
    dp[0][0] = 0;

    for (int k = 0; k < N; k++) {
        for (int i = 0; i <= sumA; i++) {
            for (int j = 0; j <= sumB; j++) {
                ndp[i][j] = dp[i][j];
            }
        }

        for (int i = 0; i <= sumA - a[k]; i++) {
            for (int j = 0; j <= sumB - b[k]; j++) {
                if (dp[i][j] == INF) continue;
                ndp[i + a[k]][j + b[k]] = min(ndp[i + a[k]][j + b[k]], dp[i][j] + c[k]);
            }
        }

        for (int i = 0; i <= sumA; i++) {
            for (int j = 0; j <= sumB; j++) {
                dp[i][j] = ndp[i][j];
            }
        }
    }

    int ans = INF;
    for (int k = 1; k <= 400; k++) {
        int x = Ma * k;
        int y = Mb * k;
        if (x <= sumA && y <= sumB) {
            ans = min(ans, dp[x][y]);
        }
    }

    if (ans == INF) printf("-1\n");
    else printf("%d\n", ans);

    return 0;
}

