int main() {
    int N, Ma, Mb;
    cin >> N >> Ma >> Mb;

    vector<long long> a(N), b(N), p(N);
    for (int i = 0; i < N; i++) cin >> a[i] >> b[i] >> p[i];

    vector<long long> d(N);
    for (int i = 0; i < N; i++) d[i] = a[i] * Mb - b[i] * Ma;

    // dp: map from sum_d -> min_cost
    map<long long, long long> dp;
    dp[0] = 0;

    for (int i = 0; i < N; i++) {
        map<long long, long long> ndp = dp;
        for (auto& [key, val] : dp) {
            long long nk = key + d[i];
            long long nv = val + p[i];
            if (ndp.find(nk) == ndp.end() || ndp[nk] > nv)
                ndp[nk] = nv;
        }
        dp = ndp;
    }

    // Find min cost with sum_d = 0, but must have selected at least one package
    // and total A, B > 0
    // dp[0] includes the empty set (cost 0), we need non-empty
    if (dp.count(0) && dp[0] > 0) {
        cout << dp[0] << endl;
    } else {
        cout << -1 << endl;
    }

    return 0;
}

#include <bits/stdc++.h>
