int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, Ma, Mb;
    cin >> N >> Ma >> Mb;

    const int INF = 1e9;

    // Constraints for this classic problem allow total A/B up to 400.
    // dp[a][b] = minimum cost to obtain exactly (a, b)
    vector<vector<int>> dp(401, vector<int>(401, INF));
    dp[0][0] = 0;

    for (int i = 0; i < N; i++) {
        int a, b, c;
        cin >> a >> b >> c;

        vector<vector<int>> ndp = dp;
        for (int x = 0; x <= 400 - a; x++) {
            for (int y = 0; y <= 400 - b; y++) {
                if (dp[x][y] == INF) continue;
                ndp[x + a][y + b] = min(ndp[x + a][y + b], dp[x][y] + c);
            }
        }
        dp.swap(ndp);
    }

    int ans = INF;
    for (int k = 1; k <= 400; k++) {
        int x = Ma * k;
        int y = Mb * k;
        if (x > 400 || y > 400) break;
        ans = min(ans, dp[x][y]);
    }

    if (ans == INF) cout << -1 << '\n';
    else cout << ans << '\n';

    return 0;
}

