        int[] b = new int[n];
        int[] c = new int[n];
        int totalA = 0, totalB = 0;

        for (int i = 0; i < n; i++) {
            parts = br.readLine().split(" ");
            a[i] = Integer.parseInt(parts[0]);
            b[i] = Integer.parseInt(parts[1]);
            c[i] = Integer.parseInt(parts[2]);
            totalA += a[i];
            totalB += b[i];
        }

        // dp[i][j] = min cost to achieve i grams of A and j grams of B
        int INF = 1_000_000_000;
        int[][] dp = new int[totalA + 1][totalB + 1];
        for (int[] row : dp) Arrays.fill(row, INF);
        dp[0][0] = 0;

        for (int idx = 0; idx < n; idx++) {
            int ai = a[idx], bi = b[idx], ci = c[idx];
            // iterate backwards to avoid using same package multiple times
            for (int i = totalA; i >= ai; i--) {
                for (int j = totalB; j >= bi; j--) {
