                        dp[i][j] = Math.min(dp[i][j], dp[i - ai][j - bi] + ci);
                    }
                }
            }
        }

        int minCost = INF;
        // Check all multiples of the target ratio
        for (int k = 1; k * ma <= totalA && k * mb <= totalB; k++) {
            int ai = k * ma;
            int bi = k * mb;
            if (dp[ai][bi] != INF) {
                minCost = Math.min(minCost, dp[ai][bi]);
            }
        }

        if (minCost == INF) {
            System.out.println(-1);
        } else {
            System.out.println(minCost);
        }
    }
