public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        long Ma = sc.nextLong(), Mb = sc.nextLong();
        long[] a = new long[N], b = new long[N], c = new long[N];
        for (int i = 0; i < N; i++) {
            a[i] = sc.nextLong(); b[i] = sc.nextLong(); c[i] = sc.nextLong();
        }
        long[] d = new long[N];
        for (int i = 0; i < N; i++) {
            d[i] = a[i] * Mb - b[i] * Ma;
        }

        int half1 = N / 2, half2 = N - half1;
        // First half: indices 0..half1-1
        HashMap<Long, Long> map = new HashMap<>();
        for (int mask = 0; mask < (1 << half1); mask++) {
            long sumD = 0, sumC = 0;
            for (int i = 0; i < half1; i++) {
                if ((mask >> i & 1) == 1) { sumD += d[i]; sumC += c[i]; }
            }
            map.merge(sumD, sumC, Math::min);
        }

        long ans = Long.MAX_VALUE;
        for (int mask = 0; mask < (1 << half2); mask++) {
            long sumD = 0, sumC = 0;
            for (int i = 0; i < half2; i++) {
                if ((mask >> i & 1) == 1) { sumD += d[half1 + i]; sumC += c[half1 + i]; }
            }
            Long val = map.get(-sumD);
            if (val != null) {
                long total = sumC + val;
                // Ensure at least one package selected (total cost > 0 means packages selected)
                if (total > 0) ans = Math.min(ans, total);
            }
        }

        if (ans == Long.MAX_VALUE) System.out.println(-1);
        else System.out.println(ans);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int N = fs.nextInt();
        int Ma = fs.nextInt();
        int Mb = fs.nextInt();

        int[] a = new int[N];
        int[] b = new int[N];
        int[] c = new int[N];

        int sumA = 0, sumB = 0;
        for (int i = 0; i < N; i++) {
            a[i] = fs.nextInt();
            b[i] = fs.nextInt();
            c[i] = fs.nextInt();
            sumA += a[i];
            sumB += b[i];
        }

        final int INF = 1_000_000_000;
        int[][] dp = new int[sumA + 1][sumB + 1];
        for (int i = 0; i <= sumA; i++) {
            Arrays.fill(dp[i], INF);
        }
        dp[0][0] = 0;

        for (int i = 0; i < N; i++) {
            int[][] next = new int[sumA + 1][sumB + 1];
            for (int x = 0; x <= sumA; x++) {
                System.arraycopy(dp[x], 0, next[x], 0, sumB + 1);
            }

            for (int x = 0; x <= sumA - a[i]; x++) {
                for (int y = 0; y <= sumB - b[i]; y++) {
                    if (dp[x][y] == INF) continue;
                    next[x + a[i]][y + b[i]] = Math.min(next[x + a[i]][y + b[i]], dp[x][y] + c[i]);
                }
            }
            dp = next;
        }

        int ans = INF;
        for (int k = 1; k * Ma <= sumA && k * Mb <= sumB; k++) {
            ans = Math.min(ans, dp[k * Ma][k * Mb]);
        }

        System.out.println(ans == INF ? -1 : ans);
    }
}

import sys
from math import gcd

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    M_a = int(next(it))
    M_b = int(next(it))

    packages = []
    for _ in range(N):
        a = int(next(it))
        b = int(next(it))
        c = int(next(it))
        packages.append((a, b, c))

    max_a = sum(p[0] for p in packages)
    max_b = sum(p[1] for p in packages)

    INF = 10**18
    # dp[sum_a][sum_b] = min cost
    dp = [[INF] * (max_b + 1) for _ in range(max_a + 1)]
    dp[0][0] = 0

    for a, b, cost in packages:
        for sum_a in range(max_a, a - 1, -1):
            for sum_b in range(max_b, b - 1, -1):
                if dp[sum_a - a][sum_b - b] != INF:
                    new_cost = dp[sum_a - a][sum_b - b] + cost
                    if new_cost < dp[sum_a][sum_b]:
                        dp[sum_a][sum_b] = new_cost

    ans = INF
    # target ratio M_a : M_b
    g = gcd(M_a, M_b)
    M_a_simple = M_a // g
    M_b_simple = M_b // g

    for sum_a in range(1, max_a + 1):
        for sum_b in range(1, max_b + 1):
            if dp[sum_a][sum_b] == INF:
                continue
            # check ratio
            if sum_a * M_b_simple == sum_b * M_a_simple:
                if dp[sum_a][sum_b] < ans:
                    ans = dp[sum_a][sum_b]

    if ans == INF:
        print(-1)
    else:
        print(ans)

if __name__ == "__main__":
    solve()
